def backfill_device_passport(apps, schema_editor):
    """Вендор и авто-роль для уже обнаруженных активов — без повторного скана (SDD §5.10)."""
    from collector.classify import classify_role
    from collector.oui import vendor_for_mac

    Asset = apps.get_model("registry", "Asset")
    updated = []
    for asset in Asset.objects.all().iterator():
        vendor = vendor_for_mac(asset.mac)
        role = classify_role(asset.ports or [], vendor, asset.hostname)
        if vendor or role:
            asset.mac_vendor = vendor or ""
            asset.role_auto = role or ""
            updated.append(asset)
    Asset.objects.bulk_update(updated, ["mac_vendor", "role_auto"], batch_size=500)


